package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamSuttaBank1 {
  private const val T = "සූත්‍ර ධර්ම හා පාලි ගාථා"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බුදුරදුන් දෙසූ 'ව්‍යග්ඝපජ්ජ සූත්‍රය' දේශනා කළේ කවර පුද්ගලයෙකු අරභයාද?", "දීඝජානු කෝලිය පුත්‍රයාට", "සිඟාල ගෘහපති පුත්‍රයාට", "විශාඛා උපාසිකාවට", "මහානාම ශාක්‍යයාට", "කක්කරපත්ත නියම්ගමේදී දීඝජානු කෝලිය පුත්‍රයාට මෙලොව පරලොව දියුණුව දෙසූහ."),
    q("ව්‍යග්ඝපජ්ජ සූත්‍රයේ ඉගැන්වෙන මෙලොව දියුණුවට හේතු වන කරුණු හතර (චතුරාර්ය ධර්ම) කුමක් ලෙස හැඳින්වේද?", "දිට්ඨධම්මහිතසුඛ සංවත්තනික ධර්ම", "සම්පරායහිතසුඛ ධර්ම", "අපායමුඛ ධර්ම", "අපරිහානීය ධර්ම", "උට්ඨාන සම්පදා, ආරක්ඛ සම්පදා, කල්‍යාණමිත්තතා, සමජීවිකතා යන සතරයි."),
    q("උට්ඨාන සම්පදා යන්නෙන් ව්‍යග්ඝපජ්ජ සූත්‍රයේ අදහස් කරන්නේ කුමක්ද?", "දැහැමිව හා උත්සාහයෙන් ධනය ඉපයීම", "ධනය ආරක්ෂා කිරීම", "අයවැය සමව පවත්වා ගැනීම", "සත්පුරුෂ මිතුරන් ඇසුරු කිරීම", "අලස නොවී කෘෂි, වෙළඳ ආදී නිවැරදි කර්මාන්තවලින් උත්සාහවන්ත වීමයි."),
    q("ආරක්ඛ සම්පදා යන්නෙහි නිවැරදි අර්ථය කුමක්ද?", "ධාර්මිකව ඉපැයූ ධනය විනාශ නොවී රැකගැනීම", "වැඩි වේලාවක් නිදා ගැනීම", "අනුන්ගේ ධනය පැහැර ගැනීම", "ණයට මුදල් ගැනීම", "රජුන්ගෙන්, සොරුන්ගෙන්, ගින්නෙන් හා ජලයෙන් ධනය ආරක්ෂා කර ගැනීමයි."),
    q("ව්‍යග්ඝපජ්ජ සූත්‍රයේ දැක්වෙන 'සමජීවිකතා' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "ආදායමට සරිලන ලෙස වියදම් පාලනය", "ආදායමට වඩා වැඩියෙන් වියදම් කිරීම", "කිසිවක් වියදම් නොකර මසුරු වීම", "ධනය සොරුන්ට දීම", "අය හා වැය සමබරව පවත්වාගෙන අරපිරිමැස්මෙන් ජීවත් වීමයි."),
    q("ව්‍යග්ඝපජ්ජ සූත්‍රයට අනුව පරලොව දියුණුව සලසන ධර්ම හතරට අයත් නොවන්නේ කුමක්ද?", "ලෝභ සම්පදා", "සද්ධා සම්පදා", "සීල සම්පදා", "චාග සම්පදා", "සද්ධා, සීල, චාග, පඤ්ඤා යනු සම්පරායහිතසුඛ ධර්ම හතරයි."),
    q("ධනය විනාශ වන දොරටු හෙවත් 'අපාය මුඛ' හතර ව්‍යග්ඝපජ්ජ සූත්‍රයේ දක්වා ඇත. එයට අයත් නොවන්නේ කුමක්ද?", "දැහැමි කෘෂිකර්මය", "ස්ත්‍රී ලෝලත්වය", "සුරා ලෝලත්වය", "සූදු ක්‍රීඩාව", "ඉත්ථිධුත්තෝ, සුරාධුත්තෝ, අක්ඛධුත්තෝ, පාපමිත්තතා අපාය මුඛ හතරයි."),
    q("ගිහි විනය ලෙස හඳුන්වනු ලබන 'සිඟාලෝවාද සූත්‍රය' දේශනා කළේ කුමන නගරයේදීද?", "රජගහ නුවරදී", "සැවැත් නුවරදී", "බරණැස් නුවරදී", "විශාලා නුවරදී", "වේළුවනාරාමයට වඩිද්දී සදිසා වඳින සිඟාල ගෘහපති පුත්‍රයාට මෙම සූත්‍රය දේශනා කළහ."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව නැගෙනහිර දිශාවෙන් සංකේතවත් කෙරෙන පිරිස කවුද?", "මව්පියන්", "ගුරුවරුන්", "අඹුදරුවන්", "හිතමිතුරන්", "මුලින්ම උපත දී රැකබලා ගන්නා මව්පියන් නැගෙනහිර දිශාව ලෙස දැක්වේ."),
    q("සිඟාලෝවාද සූත්‍රයේ දකුණු දිශාවෙන් හඳුන්වනු ලබන සමාජ කණ්ඩායම කවුද?", "ආචාර්යවරුන්", "මව්පියන්", "සේවකයන්", "පැවිදි උතුමන්", "ශිල්ප ශාස්ත්‍ර හා යහගුණ කියා දෙන ගුරුවරුන් දකුණු දිශාව ලෙස සැලකේ."),
    q("සදිසා නමස්කාරයේදී බටහිර දිශාවෙන් සංකේතවත් කෙරෙන්නේ කවුරුන්ද?", "අඹුදරුවන්", "හිතමිතුරන්", "ගුරුවරුන්", "මව්පියන්", "පවුලේ සමගිය හා සුරක්ෂිතතාව රකින භාර්යාව හා දරුවන් බටහිර දිශාවයි."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව උතුරු දිශාව නියෝජනය කරන්නේ කවුරුන්ද?", "හිතමිතුරන් හා ඥාතීන්", "මව්පියන්", "සේවකයන්", "පැවිදි උතුමන්", "විපතේදී පිහිට වන හිතමිතුරන් උතුරු දිශාව ලෙස නම් කර ඇත."),
    q("සදිසා නමස්කාරයේදී යට දිශාවෙන් හඳුන්වන්නේ කුමන පිරිසද?", "දාස කර්මකාරාදී සේවක පිරිස", "මහණ බමුණන්", "ගුරුවරුන්", "අඹුදරුවන්", "සේවකයන්ට ශක්ති පමණින් වැඩ පැවරීම හා නිසි වැටුප් දීම යට දිශාව වැඳීමයි."),
    q("සිඟාලෝවාද සූත්‍රයේ උඩ දිශාවෙන් සංකේතවත් කෙරෙන්නේ කවුරුන්ද?", "මහණ බමුණන්", "රජතුමා", "මව්පියන්", "දරුවන්", "අධ්‍යාත්මික මගපෙන්වීම ලබාදෙන ශ්‍රමණ බ්‍රාහ්මණයන් උඩ දිශාවයි."),
    q("සිඟාලෝවාද සූත්‍රයේ දැක්වෙන පුද්ගලයෙකු කළ යුතු ක්‍රියාවන් කිලිටි කරන 'සතර කර්ම ක්ලේශ' වලට අයත් නොවන්නේ කුමක්ද?", "සත්‍ය වචනය", "ප්‍රාණඝාතය", "අදත්තාදානය", "කාමමිථ්‍යාචාරය", "ප්‍රාණඝාතය, අදත්තාදානය, කාමමිථ්‍යාචාරය හා මුසාවාදය සතර කර්ම ක්ලේශ වේ."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව සැබෑ කල්‍යාණ මිත්‍රයන් වර්ග හතරට අයත් නොවන්නේ කවුද?", "අඤ්ඤදත්ථුහර මිත්‍රයා", "උපකාරක මිත්‍රයා", "සමාන සුඛදුක්ඛ මිත්‍රයා", "අත්ථක්ඛායී මිත්‍රයා", "අඤ්ඤදත්ථුහර යනු මිත්‍ර ප්‍රතිරූපක (බොරු මිතුරෙකි)."),
    q("බොරු මිතුරෙකු වන 'වචීපරම' මිත්‍රයාගේ ප්‍රධාන ලක්ෂණය කුමක්ද?", "වචනයෙන් පමණක් සංග්‍රහ කර උදව් මගහැරීම", "දුක සැප දෙකේදීම ළඟ සිටීම", "යහපත් දේ පමණක් පෙන්වා දීම", "රහස් ආරක්ෂා කිරීම", "අතීත හා අනාගත ගුණ කියමින් වචනයට පමණක් සීමා වීම වචීපරම මිත්‍රයාගේ ස්වභාවයයි."),
    q("තමාගේ යහපතට වැඩ දායක කරුණු කියා දෙන කල්‍යාණ මිත්‍රයා කවර නමකින් හැඳින්වේද?", "අත්ථක්ඛායී මිත්‍රයා", "අනුකම්පක මිත්‍රයා", "වචීපරම මිත්‍රයා", "අපායසහාය මිත්‍රයා", "පවින් වළක්වා සුගති මග පෙන්වන්නා අත්ථක්ඛායී මිත්‍රයාය."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව භෝග විනාශ මුඛ හයට අයත් වන ක්‍රියාවක් කුමක්ද?", "උත්සව සැණකෙළි නැරඹීමට ලොල් වීම", "උදෑසනින් අවදි වීම", "ශිල්ප ඉගෙනීම", "සත්පුරුෂයන් ඇසුර", "සුරාපානය, අකාල විචරණය, සමජ්ජාභිචරණය, සූදුව, පවිටු ඇසුර, අලසකම යන සයයි."),
    q("වසල සූත්‍රය දේශනා කිරීමට මූලික හේතුව වූ බමුණා කවුද?", "අග්ගික භාරද්වාජ බමුණා", "කසීභාරද්වාජ බමුණා", "සුන්දරික භාරද්වාජ", "වේරංජ බමුණා", "'මුණ්ඩක සමණක වසලක' යැයි නින්දා කළ බැවින් සැබෑ වසලයා පැහැදිලි කළහ."),
    q("වසල සූත්‍රයට අනුව පුද්ගලයෙකු වසලයෙකු හෝ බ්‍රාහ්මණයෙකු වන්නේ කුමක් මතද?", "තමා කරන ක්‍රියාවන් මත", "උපන් කුලය මත", "ධනය මත", "භාෂාව මත", "'න ජච්චා වසලෝ හෝති... කම්මනා වසලෝ හෝති' යන්නෙන් ක්‍රියාව ප්‍රධාන බව වදාළහ."),
    q("වසල සූත්‍රයට අනුව ධනවත්ව සිටියදීත් මහලු මව්පියන් පෝෂණය නොකරන්නා හඳුන්වන්නේ කෙසේද?", "වසලයෙකු ලෙස", "රහතන් වහන්සේ ලෙස", "බ්‍රාහ්මණයෙකු ලෙස", "මහා දානපතියෙකු ලෙස", "මව්පියන්ට නොසැලකීම වසල ස්වභාවයක් බව බුදුරදුන් දෙසූහ."),
    q("වසල සූත්‍රයේදී 'තමා හුවා දක්වමින් අන් අය හෙළා දකින්නා' කෙසේ හඳුන්වා ඇත්ද?", "වසලයෙකු ලෙස", "සත්පුරුෂයෙකු ලෙස", "පණ්ඩිතයෙකු ලෙස", "ධර්මධරයෙකු ලෙස", "අත්තුක්කංසන හා පරවම්භන යන අධම ගුණ ඇත්තා වසලයෙකි."),
    q("පුද්ගලයාගේ පිරිහීමට හේතු වන කරුණු විස්තර කෙරෙන සූත්‍රය කුමක්ද?", "පරාභව සූත්‍රය", "මහාමංගල සූත්‍රය", "මෙත්ත සූත්‍රය", "ධම්මචක්ක සූත්‍රය", "දේවතාවෙකු ඇසූ ප්‍රශ්නවලට පිළිතුරු ලෙස පිරිහීමේ දොරටු 12 ක් පරාභව සූත්‍රයේ දැක්වේ."),
    q("පරාභව සූත්‍රයට අනුව 'සුජානෝ භවං හෝති - සුජානෝ පරාභවෝ' යන්නෙන් දැක්වෙන්නේ කුමක්ද?", "දියුණු වන්නා හා පිරිහෙන්නා පහසුවෙන් හඳුනාගත හැකි බව", "කිසිවෙකුටත් දියුණු විය නොහැකි බව", "දෙවියන් පමණක් දියුණු වන බව", "ධනය නැතිවීම පිරිහීම බව", "ධර්මයට කැමති අය දියුණු වන අතර දහමට ද්වේෂ කරන්නෝ පිරිහෙති."),
    q("පරාභව සූත්‍රයට අනුව පළමු පිරිහීමේ කරුණ කුමක්ද?", "ධර්මයට ද්වේෂ කිරීම", "උදේ වරුවේ නිදා ගැනීම", "කුලයෙන් පහත් වීම", "වන්දනාවේ යෑම", "ධම්මකාමෝ භවං හෝති ධම්මදෙස්සී පරාභවෝ ලෙස දැක්වේ."),
    q("පරාභව සූත්‍රයේ දැක්වෙන පිරිහීමේ දොරටුවක් නොවන්නේ කුමක්ද?", "ධාර්මිකව ධනය ඉපයීම", "අසත්පුරුෂයන් ප්‍රිය කිරීම", "අලසකම හා නිද්‍රාශීලී බව", "තමාට වඩා බාල හෝ නොගැළපෙන වියේ විවාහය", "සැහැල්ලුවෙන් කල්‍යාණ මිත්‍ර ඇසුර දියුණුවේ මඟයි."),
    q("මහා මංගල සූත්‍රය දේශනා කළේ කවරෙකුගේ ප්‍රශ්නයකට පිළිතුරු වශයෙන්ද?", "දේවතාවෙකුගේ", "සක්‍ර දෙවියන්ගේ", "මහා බ්‍රහ්මයාගේ", "අනේපිඬු සිටුතුමාගේ", "වසර 12 ක් පැවති මංගල කෝලාහලය විසඳමින් මංගල කරුණු 38 ක් දෙසූහ."),
    q("මහා මංගල සූත්‍රයේ සඳහන් පළමු මංගල කරුණ කුමක්ද?", "අසේවනා ච බාලානං (අසත්පුරුෂයන් ඇසුරු නොකිරීම)", "දානඤ්ච (දන් දීම)", "බහුසච්චං (බහුශ්‍රැත බව)", "ඛන්ති (ඉවසීම)", "පුද්ගලයාගේ දියුණුවට මුලින්ම පවිටු ඇසුරින් වෙන්වීම අවශ්‍ය වේ."),
    q("මහා මංගල සූත්‍රයේ 'පතිරූප දේසවාසෝ ච' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "යහපත් සුදුසු ප්‍රදේශයක වාසය කිරීම", "ලස්සන ඇඳුම් ඇඳීම", "උසස් තනතුරක් ලැබීම", "ධනවත් පවුලක ඉපදීම", "අධ්‍යාපනයට, රැකියාවට හා දහම් ඇසීමට සුදුසු පරිසරයක විසීම උතුම් මංගල්‍යයකි."),
    q("මහා මංගල සූත්‍රයේ 'සෝවචස්සතා' යනුවෙන් දැක්වෙන මංගල කරුණ කුමක්ද?", "කීකරු බව", "නිහතමානී බව", "කළගුණ සැලකීම", "ඉවසීම", "යහපත් අවවාද අනුශාසනා පිළිගන්නා කීකරු බව සෝවචස්සතා නම් වේ."),
    q("මහා මංගල සූත්‍රයේ අවසානයේදී දැක්වෙන උසස්ම මංගල කරුණ කුමක්ද?", "අටලෝ දහමින් කම්පා නොවන නිවන් දුටු සිත", "රාජ්‍ය පාලනය ලැබීම", "ධනවත් වීම", "දිව්‍ය ලෝකයේ ඉපදීම", "'ඵුට්ඨස්ස ලෝකධම්මේහි චිත්තං යස්ස න කම්පති' ලෙස අවසන් මංගල කරුණ දැක්වේ."),
    q("තුන් බිය දුරු කිරීම සඳහා විශාලා මහනුවරදී දේශනා කළ සූත්‍රය කුමක්ද?", "රතන සූත්‍රය", "මහාමංගල සූත්‍රය", "කරණීයමෙත්ත සූත්‍රය", "ආටානාටිය සූත්‍රය", "දුර්භික්ෂ, අමනුෂ්‍ය, රෝග යන තුන් බිය දුරු කිරීමට ආනන්ද හිමිට රතන සූත්‍රය ඉගැන්වූහ."),
    q("රතන සූත්‍රයේ ප්‍රධාන වශයෙන් වර්ණනා කෙරෙන්නේ කුමක්ද?", "බුද්ධ, ධම්ම, සංඝ යන ත්‍රිවිධ රත්නයේ ගුණ", "රජුගේ වීරත්වය", "දිව්‍ය ලෝකයේ සැප", "වනාන්තරවල සුන්දරත්වය", "තෙරුවන් ගුණ සත්‍ය ක්‍රියාවක් ලෙස ගෙන ආශිර්වාද කිරීම රතන සූත්‍රයේ අන්තර්ගත වේ."),
    q("රතන සූත්‍රයේදී මහපොළොවෙහි සිටුවූ ඉන්ද්‍රඛීලයකට උපමා කර ඇත්තේ කවුද?", "සෝවාන් ආර්ය ශ්‍රාවකයා", "පෘථග්ජන පුද්ගලයා", "සක්විති රජතුමා", "දෙවියන්", "සිව් දිගින් හමන සුළඟින් නොසැලෙන ඉන්ද්‍රඛීලය මෙන් සෝවාන් පුද්ගලයා අකම්පිත වේ."),
    q("රතන සූත්‍රයේ 'නිබ්බන්ති ධීරා යථායං පදීපෝ' යන උපමාවෙන් දැක්වෙන්නේ කුමක්ද?", "තෙල් වැටි අවසන් වූ පහනක් නිවී යාම මෙන් රහතුන් පිරිනිවන් පෑම", "පහනක් දැල්වෙන ආකාරය", "පහනකින් ආලෝකය ලැබීම", "ධනය විනාශ වී යාම", "තෘෂ්ණා උපාදාන ක්ෂය වීමෙන් රහතුන් නැවත නොඉපදී පිරිනිවන් පාති."),
    q("විමර්ශන බුද්ධියෙන් සත්‍යය තෝරා ගැනීමේ නිදහස පිළිබඳව බුදුරදුන් දෙසූ 'කාලාම සූත්‍රය' දේශනා කළේ කොහිදීද?", "කේසපුත්ත නියම්ගමේදී", "රජගහ නුවරදී", "සැවැත් නුවරදී", "කපිලවස්තුවේදී", "කෝසල ජනපදයේ කේසපුත්තයේ කාලාම වැසියන්ගේ සැක දුරු කිරීමට මෙය දෙසූහ."),
    q("කාලාම සූත්‍රයට අනුව යමක් පිළිගැනීමේදී මූලික පදනම කර නොගත යුතු කරුණු ගණන කීයද?", "දහයකි", "පහකි", "සතරකි", "අටකි", "මා අනුස්සවේන, මා පරම්පරාය ආදී වශයෙන් අන්ධ විශ්වාස පිළිබඳ කරුණු 10 ක් දැක්වේ."),
    q("කාලාම සූත්‍රයේ දැක්වෙන 'මා පිටක සම්පදානේන' යන්නෙහි අර්ථය කුමක්ද?", "පොත්පත්වල ලියා තිබූ පමණින් නොපිළිගන්න", "පොත්පත් නොකියවන්න", "පොත්පත් පූජා කරන්න", "පරම්පරාවට ගරු කරන්න", "ලිඛිත ග්‍රන්ථයක සඳහන් වූ පමණින් සත්‍යය යැයි නොගෙන විමසා බැලිය යුතුය."),
    q("කාලාම සූත්‍රයට අනුව යමක් සත්‍ය හෝ යහපත් දැයි තේරුම් ගැනීමට නිර්ණායකය වන්නේ කුමක්ද?", "තමාගේම ප්‍රත්‍යක්ෂ නුවණින් කුසල් අකුසල් විමසා බැලීම", "ගුරුවරයාගේ කීම පමණක් පිළිගැනීම", "බහුතර මතය අනුගමනය කිරීම", "පරම්පරා චාරිත්‍ර රැකීම", "මෙය අකුසලයකි, නුවණැත්තන් ගරහති, දුකට හේතු වේ යැයි තම නුවණින් විමසිය යුතුය."),
    q("කරණීයමෙත්ත සූත්‍රයේ ආරම්භයේදී නිවන් පතන පුද්ගලයා තුළ තිබිය යුතු මූලික ගුණ අතර 'උජූ' හා 'සූජූ' යන්නෙහි අර්ථය කුමක්ද?", "අවංක බව හා මනාව අවංක බව", "දක්ෂ බව හා බලවත් බව", "සතුටු බව හා නිහඬ බව", "ධනවත් බව හා උගත් බව", "කයින්, වචනයෙන් හා සිතින් කෛරාටික නොවන අවංක භාවයයි."),
    q("කරණීයමෙත්ත සූත්‍රයේ 'සන්තුස්සකෝ ච සුභරෝ ච' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "ලද දෙයින් සතුටු වීම හා පහසුවෙන් පෝෂණය කළ හැකි බව", "වැඩි වශයෙන් ආහාර ගැනීම", "සමාජයෙන් වෙන්වීම", "බොහෝ කටයුතු ඇති බව", "අල්පේච්ඡ ජීවිතය මෛත්‍රී භාවනාවට පහසුවකි."),
    q("කරණීයමෙත්ත සූත්‍රයට අනුව මෛත්‍රිය වැඩිය යුතු උපමාව කුමක්ද?", "මවක් සිය එකම පුතු රකින්නාක් මෙන්", "රජෙකු රට රකින්නාක් මෙන්", "සොරෙකු ධනය රකින්නාක් මෙන්", "සිංහයෙකු ගුහාව රකින්නාක් මෙන්", "'මාතා යථා නියං පුත්තං' යනුවෙන් අසීමිත දයාවෙන් සියලු සතුන්ට මෙත් වැඩිය යුතුය."),
    q("සියලු සත්වයන් 'අවේරා, අබ්‍යාපජ්ඣා, අනීඝා, සුඛී අත්තානං පරිහරන්තු' යනු කවර පැතුමක්ද?", "වෛර, පීඩා, දුක් නැතිව සුවසේ වෙසෙත්වා යන්න", "බොහෝ ධනය ලැබෙත්වා යන්න", "බලවත් රජුන් වෙත්වා යන්න", "වෙනත් ලෝකවල උපදිත්වා යන්න", "කරණීයමෙත්ත සූත්‍රයේ මෛත්‍රී පැතුමයි."),
    q("අනුරාධපුර සමයේ ලියැවුණු ධම්මචක්කප්පවත්තන සූත්‍රය දේශනා කළ ස්ථානය කුමක්ද?", "බරණැස ඉසිපතන මිගදාය", "රජගහ නුවර වේළුවනය", "සැවැත් නුවර ජේතවනය", "ගයා ශීර්ෂය", "පස්වග තවුසන් අමතා ඇසළ පුන් පොහෝ දින ප්‍රථම ධර්ම දේශනාව පැවැත්වූහ."),
    q("ධම්මචක්කප්පවත්තන සූත්‍රයේදී පැවිද්දන් විසින් සේවනය නොකළ යුතු අන්ත දෙක කුමක්ද?", "කාමසුඛල්ලිකානුයෝගය හා අත්තකිලමථානුයෝගය", "දානය හා ශීලය", "සමථය හා විදර්ශනාව", "ලෝකෝත්තර හා ලෞකික මාර්ගය", "මෙම අන්ත දෙක හැර මධ්‍යම ප්‍රතිපදාව අනුගමනය කළ යුතුය."),
    q("මනුෂ්‍යයන් පහත් හා උසස් ක්‍රියාවල යෙදෙන විට එම අවස්ථා විනිවිද දකින 'ධම්මපදය' අයත් වන්නේ කුමන පිටකයටද?", "සූත්‍ර පිටකයට", "විනය පිටකයට", "අභිධර්ම පිටකයට", "වංශකතාවලට", "ධම්මපදය සූත්‍ර පිටකයේ ඛුද්දක නිකායට අයත් ගාථා 423 ක ග්‍රන්ථයකි."),
    q("ධම්මපදයේ පළමු ගාථාව වන 'මනෝපුබ්බංගමා ධම්මා' යන්නෙහි ප්‍රධාන පණිවිඩය කුමක්ද?", "සියලු ක්‍රියාවන්ට සිත මුල් වන බව", "සියල්ලට ශරීරය මුල් වන බව", "ධනය සියල්ලට මුල් වන බව", "වචනය පමණක් වැදගත් බව", "දූෂිත සිතින් හෝ පහන් සිතින් ක්‍රියා කරන විට දුක සැප පසුපස එයි."),
    q("ධම්මපදයේ 'අප්පමාදෝ අමතපදං - පමාදෝ මච්චුනෝ පදං' යන්නෙහි අර්ථය කුමක්ද?", "අප්‍රමාදය නිවනට මඟ වන අතර ප්‍රමාදය මරණයට මඟයි", "ප්‍රමාදය සැපයට මඟයි", "අප්‍රමාදය ධනයට පමණක් මඟයි", "මරණයට බිය විය යුතු නැත", "කුසල් දහම්හි අප්‍රමාදී වීම නිවන් දැකීමේ මූලික පදනමයි."),
    q("ධම්මපදයේ 'නහි වේරේන වේරාණි - සම්මන්තීධ කුදාචනං' ගාථාවෙන් උගන්වන්නේ කුමක්ද?", "වෛරයෙන් වෛරය කිසිදා නොසන්සිඳෙන බව", "වෛරයට වෛරයෙන් පිළිතුරු දිය යුතු බව", "සතුරන් විනාශ කළ යුතු බව", "අවෛරය දුර්වලකමක් බව", "අවෛරයෙන් හෙවත් මෛත්‍රියෙන්ම වෛරය සංසිඳේ."),
    q("ධම්මපදයේ 'නත්ථි රාගසමෝ අග්ගි' යන ගාථාවෙන් රාගය, ද්වේෂය, මෝහය උපමා කර ඇත්තේ පිළිවෙළින් කුමකටද?", "ගින්න, කෝපය නැමැති පහර, දැල", "ජලය, සුළඟ, පොළොව", "රන්, රිදී, මැණික්", "හිරු, සඳු, තරු", "රාගය වැනි ගින්නක් නැත, ද්වේෂය වැනි දෝෂයක් නැත, මෝහය වැනි දැලක් නැත."),
    q("ධම්මපදයේ 'සබ්බපාපස්ස අකරණං - කුසලස්ස උපසම්පදා' යනු කුමක්ද?", "සියලු බුදුවරුන්ගේ පොදු අනුශාසනය (ඕවාද ප්‍රාතිමෝක්ෂය)", "පංච ශීලය පමණි", "රාජ නීතිය", "සතර සංග්‍රහ වස්තු", "පවින් වැළකීම, කුසල් රැස් කිරීම හා සිත පිරිසිදු කිරීම සර්ව බුද්ධ ශාසනයයි."),
    q("ධම්මපදයේ 'ආරෝග්‍යා පරමා ලාභා - සන්තුට්ඨි පරමං ධනං' ගාථාව අනුව පරම ඥාතියා කවුද?", "විශ්වාසය (විස්සාසා පරමා ඤාති)", "ධනය", "නෑදෑයා", "රජතුමා", "නිරෝගිකම පරම ලාභයත්, සතුට පරම ධනයත්, විශ්වාසය පරම ඥාතියාත් වේ."),
    q("ධම්මපදයේ 'යෝ ච වස්සසතං ජීවේ - දුස්සීලෝ අසමාහිතෝ' යන්නෙන් කවර පුද්ගලයෙකු අගය කෙරේද?", "සිල්වත්ව සමාහිතව එක් දිනක් ජීවත් වන්නා", "දුසිල්වත්ව සියවසක් ජීවත් වන්නා", "ධනවත්ව සියවසක් සිටින්නා", "අලසව සියවසක් සිටින්නා", "ගුණදහමින් පිරි එක් දිනක ජීවිතය පවා අර්ථවත් බව දැක්වේ."),
    q("ධම්මපදයේ 'කුසග්ගේනපි බාලෝ' යන්නෙන් හෙළා දකින්නේ කුමන දුර්වලතාවයද?", "බොරු තපස් රැකීම හා අනුන් රැවටීම", "උත්සාහයෙන් වැඩ කිරීම", "සත්‍යය කතා කිරීම", "මෛත්‍රී භාවනාව", "අභ්‍යන්තර පිරිසිදුකම නැති බාහිර ආඩම්බර තපස නිෂ්ඵල බව දැක්වේ."),
    q("ධම්මපදයේ 'පුප්ඵානි හේව පචිනන්තං' ගාථාවෙන් මනුෂ්‍යයාට සිහිපත් කරන්නේ කුමක්ද?", "කාමයන් රැස් කරමින් සිටින විට මරණය පැමිණෙන බව", "මල් පූජා කිරීමේ ආනිසංස", "උද්‍යාන අලංකරණය", "රාජ්‍ය පාලන ක්‍රම", "මල් නෙළන මිනිසෙකු මහා ගංවතුරකට හසු වන්නා සේ මරු පැමිණෙන බව දැක්වේ."),
    q("ධම්මපදයේ 'න පරේසං විලෝමානි' ගාථාවෙන් උපදෙස් දෙන්නේ කුමක් ගැනද?", "අනුන්ගේ වැරදි නොසොයා තමාගේ අඩුපාඩු සොයා බලන ලෙස", "අනුන්ගේ වැරදි ප්‍රසිද්ධ කරන ලෙස", "තමා ගැන ආඩම්බර වන ලෙස", "විවේචනවලට කෝප වන ලෙස", "තමා කළ නොකළ දේ ගැන ස්වයං විමර්ශනය කිරීම දියුණුවේ මගයි."),
    q("ධම්මපදයේ 'අත්තා හි අත්තනෝ නාථෝ' යන පාඨයෙන් පෙන්වා දෙන ශ්‍රේෂ්ඨ සත්‍යය කුමක්ද?", "තමාගේ විමුක්තිය තමා විසින්ම සලසා ගත යුතු බව", "අන් අයගෙන් විමුක්තිය පැතිය යුතු බව", "රජුගේ පිහිට පමණක් ප්‍රමාණවත් බව", "උත්සාහයෙන් පලක් නැති බව", "බුදුදහම ආත්ම විශ්වාසය හා ස්වෝත්සාහය අගය කරයි."),
    q("ධම්මපදයේ 'දුන්නිග්ගහස්ස ලහුනෝ' ගාථාවෙන් දක්වන්නේ කුමක් දමනය කිරීමේ වැදගත්කමද?", "සිත දමනය කිරීමේ වැදගත්කම", "වචනය පමණක් පාලනය කිරීම", "ශරීරය දුබල කිරීම", "මිතුරන් පාලනය කිරීම", "වහා වෙනස් වන සිත දමනය කිරීම සැප ගෙන දෙයි."),
    q("ධම්මපදයේ 'මාතා මිත්තං සකේ ඝරේ' යන්න අඩංගු වන්නේ කුමන සූත්‍රයට අනුරූපවද?", "දේවතා සංයුත්තයේ කිං සූත්‍රයට", "වසල සූත්‍රයට", "පරාභව සූත්‍රයට", "ආලවක සූත්‍රයට", "නිවසේදී මව මිතුරා වන බව දෙවියෙකුගේ ප්‍රශ්නයට පිළිතුරක් ලෙස වදාළහ."),
    q("ආලවක සූත්‍රයේදී 'කථං සු ලභතේ පඤ්ඤං' (ප්‍රඥාව ලබන්නේ කෙසේද) යන්නට බුදුරදුන් දුන් පිළිතුර කුමක්ද?", "ධර්ම ශ්‍රවණයට කැමතිවී අවධානයෙන් ඇසීමෙන් (සුස්සූසා ලභතේ පඤ්ඤං)", "ධනය රැස් කිරීමෙන්", "සටන් කිරීමෙන්", "නින්දෙන්", "සද්ධර්මය මනාව ශ්‍රවණය කිරීමෙන් ප්‍රඥාව උපදී."),
    q("ආලවක සූත්‍රයේදී 'කථං සු වින්දතේ ධනං' (ධනය ලබන්නේ කෙසේද) යන්නට දුන් පිළිතුර කුමක්ද?", "සුදුසු කර්මාන්තයේ නොපසුබට උත්සාහයෙන් (උට්ඨාතා වින්දතේ ධනං)", "සොරකම් කිරීමෙන්", "සූදුවෙන්", "උදාසීන වීමෙන්", "උත්සාහවන්ත හා දැහැමි කාර්යශූර පුද්ගලයා ධනය උපයයි."),
    q("ආලවක සූත්‍රයේ 'කථං සු කිත්තිං පප්පෝති' (කීර්තිය ලබන්නේ කෙසේද) යන්නට පිළිතුර කුමක්ද?", "සත්‍ය වචනයෙන් (සච්චේන කිත්තිං පප්පෝති)", "දන් නොදී සිටීමෙන්", "බොරු කීමෙන්", "රෞද්‍ර වීමෙන්", "සත්‍යවාදී පුද්ගලයා සමාජයේ කීර්තියට පත් වේ."),
    q("ආලවක සූත්‍රයේ 'කථං මිත්තානි ගන්ථති' (මිතුරන් බැඳ ගන්නේ කෙසේද) යන්නට පිළිතුර කුමක්ද?", "දන් දීමෙන් හා පරිත්‍යාගයෙන් (දදං මිත්තානි ගන්ථති)", "මසුරුකමින්", "කේළාම් කීමෙන්", "තර්ජනය කිරීමෙන්", "පරිත්‍යාගශීලී පුද්ගලයාට මිතුරන් බැඳේ."),
    q("ආලවක සූත්‍රයේදී සියලු රස අතරින් උතුම්ම රසය කුමක් බව දේශනා කළේද?", "සත්‍ය රසය (සච්චං හවේ සාදුතරං රසානං)", "මී පැණි රසය", "අමෘත රසය", "කිරි රසය", "සත්‍යය සියලු රසයන්ට වඩා මිහිරිම රසයයි."),
    q("බුදුරදුන් දෙසූ 'සත්ත සූරියුග්ගමන සූත්‍රයෙන්' පැහැදිලි කරන ප්‍රධාන දහම් කරුණ කුමක්ද?", "සියලු සංස්කාරයන්ගේ අනිත්‍ය ස්වභාවය", "සූර්ය වන්දනාව", "ජ්‍යොතිෂ ශාස්ත්‍රය", "ගොවිතැන් ක්‍රම", "සූර්යයන් හතක් පායා ලෝකය පවා විනාශ වන බව පෙන්වා අනිත්‍යය අවධාරණය කළහ."),
    q("බුදුදහමේ සඳහන් 'බ්‍රහ්මජාල සූත්‍රය' දීඝ නිකායේ කුමන වග්ගයට අයත්ද?", "සීලක්ඛන්ධ වග්ගයට", "මහා වග්ගයට", "පාථික වග්ගයට", "උපරිපණ්ණාසකයට", "දීඝ නිකායේ පළමු සූත්‍රය වන බ්‍රහ්මජාල සූත්‍රයේ දෘෂ්ටි 62 ක් විග්‍රහ වේ."),
    q("ගිහි කෙනෙකුට අදාළ අපරාධ හා සමාජ අපගමනයට මුල් වන ආර්ථික දුප්පත්කම පෙන්වන සූත්‍රය කුමක්ද?", "චක්කවත්ති සීහනාද සූත්‍රය", "කරණීයමෙත්ත සූත්‍රය", "රතන සූත්‍රය", "අනත්තලක්ඛණ සූත්‍රය", "රාජ්‍ය පාලකයා දුගී ජනතාවට ධනය නොදුන් කල දරිද්‍රතාව හා අපරාධ වැඩෙන බව දැක්වේ."),
    q("දැහැමි රාජ්‍ය පාලකයා වර්ෂාවට හා අස්වැන්නට පවා හේතු වන බව දක්වන සූත්‍රය කුමක්ද?", "කූටදන්ත සූත්‍රය", "ආලවක සූත්‍රය", "සිඟාලෝවාද සූත්‍රය", "වසල සූත්‍රය", "යාග පූජා වෙනුවට ආර්ථික සහන සලසා සාමය ඇති කිරීමේ වැදගත්කම කූටදන්ත සූත්‍රයේ එයි."),
    q("සැබෑ ශාන්තිය ඇති වන්නේ සත්ව බිලි පූජාවෙන් නොව දාන ශීලාදී ගුණධර්මවලින් බව කූටදන්ත බමුණාට දෙසුවේ කුමන සූත්‍රයේද?", "කූටදන්ත සූත්‍රයේ", "සෝණදණ්ඩ සූත්‍රයේ", "තේවිජ්ජ සූත්‍රයේ", "අම්බට්ඨ සූත්‍රයේ", "සත්ව හිංසාවෙන් තොර නිවැරදි යාගය දාන, සීල හා සරණාගමනය බව පැහැදිලි කළහ."),
    q("බ්‍රහ්ම ලෝකයේ ඉපදීමේ මාර්ගය සතර බ්‍රහ්ම විහරණ වැඩීම බව බමුණන්ට දෙසූ සූත්‍රය කුමක්ද?", "තේවිජ්ජ සූත්‍රය", "වසල සූත්‍රය", "ධම්මචක්ක සූත්‍රය", "පරාභව සූත්‍රය", "වසෙට්ඨ හා භාරද්වාජ තරුණ බමුණන්ට බ්‍රහ්ම සහව්‍යතා මග දේශනා කළහ."),
    q("ගිහි ජීවිතයේ අනර්ථකර බව හා පැවිදි ජීවිතයේ ප්‍රතිඵල අජාසත් රජුට දේශනා කළ සූත්‍රය කුමක්ද?", "සාමඤ්ඤඵල සූත්‍රය", "මහාපරිනිබ්බාන සූත්‍රය", "සංගීති සූත්‍රය", "සක්කපඤ්හ සූත්‍රය", "ජීවක අඹ උයනේදී ශ්‍රමණ භාවයේ දිට්ඨධම්මික හා ලෝකෝත්තර පල දෙසූහ."),
    q("මහලු පූජකයෙකු වූ සෝණදණ්ඩ බමුණාට සැබෑ බ්‍රාහ්මණයා සතු ගුණාංග ලෙස බුදුරදුන් දෙසූ ප්‍රධාන දෙක කුමක්ද?", "සීලය හා ප්‍රඥාව", "කුලය හා ධනය", "වර්ණය හා බලය", "වේද මන්ත්‍ර හා යාග", "සීලය හා ප්‍රඥාව එකිනෙක පිරිසිදු කරන බව සෝණදණ්ඩ සූත්‍රයේ දැක්වේ."),
    q("ජීවිතයේ අනිත්‍ය ස්වභාවය පෙන්වන 'රාජ්‍ය පාලකයාගේ මැදුරට යන රථ හතේ උපමාව' ඇතුළත් සූත්‍රය කුමක්ද?", "රථවිනීත සූත්‍රය", "අග්ගඤ්ඤ සූත්‍රය", "චූලකම්මවිභංග සූත්‍රය", "කකචූපම සූත්‍රය", "සීල විසුද්ධියේ සිට ඥානදස්සන විසුද්ධිය දක්වා නිවන් මග රථ හතකින් උපමා කෙරේ."),
    q("සතුරෙකු කියතකින් අත්පා කපන විට පවා තරහ නොගෙන මෙත් වැඩිය යුතු බව දැක්වෙන සූත්‍රය කුමක්ද?", "කකචූපම සූත්‍රය", "වම්මික සූත්‍රය", "සල්ලේඛ සූත්‍රය", "දාරුක්ඛන්ධූපම සූත්‍රය", "මජ්ඣිම නිකායේ කකචූපම සූත්‍රයේ ඉවසීමේ උපරිම සීමාව දැක්වේ."),
    q("මිනිසා විවිධ වූ සැප දුක්, ආයුෂ, රූප සම්පත් හා ප්‍රඥාවෙන් වෙනස් වීමට හේතුව කර්මය බව දෙසූ සූත්‍රය කුමක්ද?", "චූලකම්මවිභංග සූත්‍රය", "මහාමංගල සූත්‍රය", "රතන සූත්‍රය", "වසල සූත්‍රය", "සුභ මාණවකයාගේ ප්‍රශ්න 14 ට පිළිතුරු ලෙස මෙම සූත්‍රය දේශනා කළහ."),
    q("චූලකම්මවිභංග සූත්‍රයට අනුව දීර්ඝායුෂ ලැබීමට හේතු වන කුසල කර්මය කුමක්ද?", "ප්‍රාණඝාතයෙන් වැළකී සතුන්ට දයාව දැක්වීම", "වස්ත්‍ර පූජා කිරීම", "ආහාර පූජා කිරීම", "පැවිදි උතුමන්ගෙන් ප්‍රශ්න ඇසීම", "සතුන් නොමරා අභය දීම දීර්ඝායුෂ ලැබීමට හේතු වේ."),
    q("චූලකම්මවිභංග සූත්‍රයට අනුව කෙනෙකු උසස් ප්‍රඥාවන්තයෙකු වීමට හේතු වන කර්මය කුමක්ද?", "නුවණැති මහණ බමුණන් වෙත ගොස් කුසල් අකුසල් විමසීම", "ඊර්ෂ්‍යා නොකිරීම", "කෝප නොවීම", "බොහෝ වස්තු රැස් කිරීම", "සත්‍යය සොයා උගතුන්ගෙන් ප්‍රශ්න විමසීම ප්‍රඥාව ලැබීමට හේතු වේ."),
    q("චූලකම්මවිභංග සූත්‍රයට අනුව බොහෝ භෝග සම්පත් ලැබීමට හේතු වන්නේ කුමක්ද?", "මහණ බමුණන්ට හා දුගීන්ට ආහාරපානාදිය දන් දීම", "තරහ නොගැනීම", "කෘතඥ නොවීම", "සතුන්ට හිංසා නොකිරීම", "දානය හා පරිත්‍යාගය මහා භෝග සම්පත් උදා කරයි."),
    q("ධර්මය පහුරකට උපමා කරමින් එය තරණය කිරීම සඳහා මිස කර තබාගෙන යෑමට නොවන බව දෙසූ සූත්‍රය කුමක්ද?", "අලගද්දූපම සූත්‍රය", "කකචූපම සූත්‍රය", "මධුපිණ්ඩික සූත්‍රය", "සච්චවිභංග සූත්‍රය", "කුල්ලූපම ධර්ම දේශනාව අලගද්දූපම සූත්‍රයේ ඇතුළත් වේ."),
    q("සුභ මාණවකයා මෙන්ම රෝගී නකුලපිතාට 'කය ගිලන් වුවත් සිත ගිලන් නොකර ගන්න' යැයි වදාළේ කවුද?", "බුදුරජාණන් වහන්සේ", "සැරියුත් හිමි", "මුගලන් හිමි", "ආනන්ද හිමි", "ආතුරකායස්ස මේ සතෝ චිත්තං අනාතුරං භවිස්සති යනුවෙන් අවවාද කළහ."),
    q("අසූහාර දහසක් ධර්මස්කන්ධයෙන් පැහැදිලි කෙරෙන නිවන් මග කෙටියෙන් දැක්වෙන සූත්‍රය කුමක්ද?", "මහාසතිපට්ඨාන සූත්‍රය", "මහානිදාන සූත්‍රය", "දීඝනඛ සූත්‍රය", "අග්ගඤ්ඤ සූත්‍රය", "ඒකායනෝ අයං භික්ඛවේ මග්ගෝ යනුවෙන් සතිපට්ඨානය වර්ණනා කළහ."),
    q("ලෝකයේ හටගැනීම හා පරිණාමය පිළිබඳ බෞද්ධ සමාජ විද්‍යාත්මක විග්‍රහය ඇතුළත් සූත්‍රය කුමක්ද?", "අග්ගඤ්ඤ සූත්‍රය", "පායාසි සූත්‍රය", "බ්‍රහ්මජාල සූත්‍රය", "ලක්ඛණ සූත්‍රය", "කුල භේදයේ නිසරු බව හා සමාජ පරිණාමය අග්ගඤ්ඤ සූත්‍රයේ විස්තර වේ."),
    q("අභිධර්මය නැති වුවත් පරලොවක් ඇති බව තාර්කික උපමා රැසකින් පෙන්වා දෙන සූත්‍රය කුමක්ද?", "පායාසි රාජඤ්ඤ සූත්‍රය", "සාමඤ්ඤඵල සූත්‍රය", "මහාපරිනිබ්බාන සූත්‍රය", "සංගීති සූත්‍රය", "කුමාර කාශ්‍යප හිමියන් හා පායාසි රජු අතර සංවාදය මෙහි ඇතුළත්ය."),
    q("නින්දාවේදී කෝප නොවී ප්‍රශංසාවේදී උදම් නොවිය යුතු බව බුදුරදුන් භික්ෂූන්ට වදාළේ කුමන සූත්‍රයේද?", "බ්‍රහ්මජාල සූත්‍රයේ", "ආනාපානසති සූත්‍රයේ", "මංගල සූත්‍රයේ", "රතන සූත්‍රයේ", "බුදු, දහම්, සඟ ගුණ කීමේදී හෝ නින්දා කිරීමේදී මධ්‍යස්ථව කරුණු පහදන ලෙස වදාළහ."),
    q("පව් කරන්නන්ට මරණින් පසු ලැබෙන විපාක සිහි ගන්වන 'දේවදූත සූත්‍රයේ' පළමු දේවදූතයා කවුද?", "අලුත උපන් ළදරුවා", "මහල්ලා", "රෝගියා", "මළ සිරුර", "ළදරුවා, මහල්ලා, රෝගියා, දඬුවම් ලබන සොරා හා මළමිනිය පංච දේවදූතයෝ වෙති."),
    q("බුදුරදුන් තමන්ගේ අවසන් දිනවල ධර්ම චාරිකාව හා පිරිනිවන් පෑම විස්තර වන දීර්ඝතම සූත්‍රය කුමක්ද?", "මහාපරිනිබ්බාන සූත්‍රය", "මහාසමය සූත්‍රය", "මහාසීහනාද සූත්‍රය", "මහාගෝවින්ද සූත්‍රය", "සප්ත අපරිහානීය ධර්ම හා පරිනිර්වාණ සිදුවීම් දීඝ නිකායේ මෙම සූත්‍රයේ එයි."),
    q("ගිහි පැවිදි දෙපිරිසේම සිතේ ඇතිවන අකුසල් සංසිඳුවා ගැනීමට උගන්වන සූත්‍රය කුමක්ද?", "සල්ලේඛ සූත්‍රය", "ධම්මචක්ක සූත්‍රය", "රතන සූත්‍රය", "වසල සූත්‍රය", "සිතේ කෙලෙස් ලිහා හැරීම පිළිබඳ කරුණු 44 ක් සල්ලේඛ සූත්‍රයේ දැක්වේ."),
    q("නියමිත වෙලාවේදී නිවැරදිව ප්‍රශ්න විමසා ධර්ම සාකච්ඡා කිරීමට සැරියුත් හිමියන් දෙසූ සූත්‍රය කුමක්ද?", "සංගීති සූත්‍රය", "දසඋත්තර සූත්‍රය", "වම්මික සූත්‍රය", "පටිසම්භිදා සූත්‍රය", "නිගණ්ඨ නාථපුත්තගේ අභාවයෙන් පසු ධර්මය සමගියෙන් පවත්වා ගැනීමට සැරියුත් හිමි දෙසූහ."),
    q("මව්පියන්ට කෘතගුණ සැලකීමේ අගය දැක්වෙන 'සබ්‍රහ්මක සූත්‍රය'ට අනුව මව්පියන්ට සැලකීම සමාන වන්නේ කුමකටද?", "බ්‍රහ්මයාට හා පූර්වාචාර්යවරුන්ට සැලකීමට", "දිව්‍ය රාජයෙකුට සැලකීමට", "සේනාපතියෙකුට සැලකීමට", "වෙළඳ නායකයෙකුට සැලකීමට", "මව්පියන් බ්‍රහ්ම, පුබ්බාචරිය හා ආහුනෙය්‍ය යන නම්වලින් හැඳින්වේ."),
    q("වෛරය නොකර ඉවසීමෙන් ජය ගන්නා අයුරු පෙන්වන 'රාජෝවාද ජාතකයේ' බ්‍රහ්මදත්ත රජුගේ ප්‍රතිපත්තිය කුමක්ද?", "අක්කෝධේන ජිනේ කෝධං", "වෛරයට වෛර කිරීම", "සටනින් ජය ගැනීම", "බලයෙන් යටපත් කිරීම", "කෝප වන්නා කෝප නොවීමෙන් ද, අසාධාරණය යහපතින් ද දිනිය යුතුය."),
    q("ධනය ඇතිව සිටින තැනැත්තා ණය නැති බව, සතුටින් භුක්ති විඳීම ආදිය ලබන සැප කවර සූත්‍රයේ එයිද?", "අණණ සූත්‍රයේ", "ව්‍යග්ඝපජ්ජ සූත්‍රයේ", "ආලවක සූත්‍රයේ", "පරාභව සූත්‍රයේ", "අත්ථි සුඛ, භෝග සුඛ, අණණ සුඛ, අනවජ්ජ සුඛ යන ගිහි සැප හතර අණණ සූත්‍රයේ දැක්වේ."),
    q("බුදුරදුන් දෙසූ 'පත්තකම්ම සූත්‍රයේ' ගිහියෙකු විසින් දැහැමි ධනයෙන් කළ යුතු නිවැරදි වියදම් කීයක් දැක්වේද?", "පහකි (පංච බලි)", "දෙකකි", "තුනකි", "හතකි", "ඥාති, අතිථි, පුබ්බපේත, රාජ, දේවතා යන පංච බලි කර්ම ඉටු කළ යුතුය."),
    q("වන රෝපණය, මල් උයන් හා පැන් පොකුණු තැනීම දිවා රෑ දෙකේ පින් වැඩෙන ක්‍රියා බව දැක්වෙන සූත්‍රය කුමක්ද?", "වනරෝප සූත්‍රය", "ආලවක සූත්‍රය", "කසීභාරද්වාජ සූත්‍රය", "මංගල සූත්‍රය", "ආරාම රෝපා වන රෝපා යනුවෙන් පරිසර සංරක්ෂණයේ අගය වනරෝප සූත්‍රයේ වදාළහ.")
  )
}
